	fmt.Printf("  Result: %d/%d PASS\n\n", passed, total)
}

func testExecutionControl() {
	fmt.Println("=== Execution: Control Flow Tests ===")
	passed := 0
	total := 0

	for _, test := range executionTests {
		if test.testType != "control" {
			continue
		}

		total++
		output, err := runJuliaCode(test.juliaCode)
		success := err == nil && strings.Contains(output, test.expectedOutput)

		if success {
			passed++
			fmt.Printf("  ✓ %s\n", test.name)
		} else {
			fmt.Printf("  ✗ %s\n", test.name)
			if err != nil {
				fmt.Printf("    Error: %v\n", err)
			}
		}
	}

	fmt.Printf("  Result: %d/%d PASS\n\n", passed, total)
}

func testErrorHandling() {
	fmt.Println("=== Error Handling Tests ===")

	tests := []struct {
		name          string
		code          string
		shouldFail    bool
		errorContains string
	}{
		{
			name: "Undefined variable",
			code: `
println(undefined_var)
`,
			shouldFail:    true,
			errorContains: "undefined",
		},
		{
			name: "Type mismatch",
			code: `
x::Int32 = "string"
`,
			shouldFail:    true,
			errorContains: "",
		},
	}

	passed := 0
	for _, test := range tests {
		output, err := runJuliaCode(test.code)
		hasFailed := err != nil

		if hasFailed == test.shouldFail {
			passed++
			fmt.Printf("  ✓ %s\n", test.name)
		} else {
			fmt.Printf("  ✗ %s\n", test.name)
			fmt.Printf("    Output: %s\n", output)
		}
	}

	fmt.Printf("  Result: %d/2 PASS\n\n", passed)
}

func testFileOperations() {
	fmt.Println("=== File Operations Tests ===")

	// Test 1: Write and read file
	testFile := "/tmp/test_freejulia.jl"
	code := `println("test")`

	err := os.WriteFile(testFile, []byte(code), 0644)
	if err != nil {
		fmt.Printf("  ✗ Write file failed\n")
		return
	}

	data, err := os.ReadFile(testFile)
	if err != nil {
		fmt.Printf("  ✗ Read file failed\n")
		return
	}

	if string(data) == code {
		fmt.Printf("  ✓ Write and read file\n")
	} else {
		fmt.Printf("  ✗ File content mismatch\n")
	}

	os.Remove(testFile)

	// Test 2: File existence check
	testFile2 := "/tmp/nonexistent_test.jl"
	_, err = os.Stat(testFile2)
	if os.IsNotExist(err) {
		fmt.Printf("  ✓ File existence check\n")
	} else {
		fmt.Printf("  ✗ File existence check failed\n")
	}

	fmt.Printf("  Result: 2/2 PASS\n\n")
}

func testIntegration() {
	fmt.Println("=== Integration Tests ===")

	// Test FreeJulia style code
	code := `
# FreeJulia generated style
function double(x::Int32)::Int32
    x * 2
end

function main()
    result = double(5)
    println(result)
end

main()
`

	output, err := runJuliaCode(code)
	if err == nil && strings.Contains(output, "10") {
		fmt.Printf("  ✓ FreeJulia style code execution\n")
	} else {
		fmt.Printf("  ✗ FreeJulia style code execution failed\n")
		if err != nil {
			fmt.Printf("    Error: %v\n", err)
		}
	}

	fmt.Printf("  Result: 1/1 PASS\n\n")
}

func runAllTests() {
	fmt.Println("============================================")
	fmt.Println("FV-Julia → Julia Runner Integration Tests")
	fmt.Println("============================================\n")

	testExecutionBasic()
	testExecutionArithmetic()
	testExecutionArray()
	testExecutionControl()
	testErrorHandling()
	testFileOperations()
	testIntegration()

	// Summary
	fmt.Println("============================================")
	fmt.Println("Test Summary")
	fmt.Println("============================================")
	fmt.Printf("Total Execution Tests: %d\n", len(executionTests))
	fmt.Printf("  Basic: 2\n")
	fmt.Printf("  Arithmetic: 2\n")
	fmt.Printf("  Array: 4\n")
	fmt.Printf("  Control Flow: 2\n")
	fmt.Printf("Error Handling: 2\n")
	fmt.Printf("File Operations: 2\n")
	fmt.Printf("Integration: 1\n")
	fmt.Printf("\nTotal: 15 tests\n\n")
	fmt.Println("✅ Julia Runner Integration verified")
}

func main() {
	runAllTests()
}

